CREATE TABLE activities("id" uuid PRIMARY KEY,"owner_id" uuid,"type" text,"subject" text,"body" text,"due_date" timestamp with time zone,"completed" boolean,"related_lead_id" uuid,"related_contact_id" uuid,"related_company_id" uuid,"related_deal_id" uuid,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"outcome" text,"outcome_set_at" timestamp with time zone,"external_ids" jsonb,"hs_raw" jsonb,"duration_ms" integer,"disposition" text,"recording_url" text,"meeting_outcome" text,"meeting_location" text,"task_status" text,"task_priority" text,"email_direction" text,"email_status" text,"hubspot_owner_id" text,"hs_object_id" text,"hs_createdate" timestamp with time zone,"hs_lastmodifieddate" timestamp with time zone,"mentions" uuid[],"attachments" jsonb,"relink_checked_at" timestamp with time zone,"workspace_id" uuid,"deleted_at" timestamp with time zone,"created_by" uuid,"recording_sid" text,"recording_duration_seconds" integer,"recording_channels" integer,"transcription" text,"transcription_status" text,"transcription_model" text,"related_ticket_id" uuid,"custom_fields" jsonb,"meeting_key" text,"remind_before_minutes" integer,"reminder_sent_at" timestamp with time zone,"assigned_to" uuid,"activity_date" timestamp with time zone,"task_type" text,"recurrence" jsonb,"recurrence_parent_id" uuid,"contacted_contact_ids" uuid[],"pinned_at" timestamp with time zone,"follow_up_of" uuid);
CREATE TABLE email_messages("id" uuid PRIMARY KEY,"owner_id" uuid,"account_id" uuid,"thread_id" uuid,"provider_message_id" text,"direction" text,"from_email" text,"from_name" text,"to_emails" text[],"cc_emails" text[],"bcc_emails" text[],"subject" text,"body_html" text,"body_text" text,"snippet" text,"in_reply_to" text,"message_id_header" text,"headers" jsonb,"has_attachments" boolean,"attachments" jsonb,"sent_at" timestamp with time zone,"received_at" timestamp with time zone,"open_count" integer,"click_count" integer,"first_opened_at" timestamp with time zone,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"workspace_id" uuid);